  "Greeting_Category3": {"ko":"휴' 건강습관","en":"Hue's Healthy Habits","ja":"「ヒュー」の健康習慣","zh":"“Hue”的健康习惯","vi":"Thói quen lành mạnh của 'Hue'","th":"นิสัยรักสุขภาพของ 'ฮยู'","ru":"Здоровые привычки «Хью»","id":"Kebiasaan Sehat 'Hue'"},
